import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { PRODUCTS, CATEGORIES, TRUST_BADGES } from '../../data/products';
import { CONTENT } from '../../constants/content';
import ProductCard from '../../components/product/ProductCard/ProductCard';
import Button from '../../components/common/Button/Button';
import styles from './HomePage.module.css';

const HomePage = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [activeTab, setActiveTab] = useState('ALL');
  const navigate = useNavigate();

  const heroSlides = [
    {
      bg: 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=1400&q=80',
      title: CONTENT.HERO_TITLE_1,
      subtitle: CONTENT.HERO_SUBTITLE_1,
    },
    {
      bg: 'https://images.unsplash.com/photo-1573408301185-9519f94a5d3a?w=1400&q=80',
      title: CONTENT.HERO_TITLE_2,
      subtitle: CONTENT.HERO_SUBTITLE_2,
    },
    {
      bg: 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?w=1400&q=80',
      title: CONTENT.HERO_TITLE_3,
      subtitle: CONTENT.HERO_SUBTITLE_3,
    },
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % 3);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  const tabs = ['ALL', 'NECKLACES', 'BRACELETS', 'EARRINGS', 'RINGS'];
  const filtered =
    activeTab === 'ALL'
      ? PRODUCTS.slice(0, 8)
      : PRODUCTS.filter((p) => p.category.toUpperCase() === activeTab).slice(0, 8);




  return (
    <div className={styles.page}>
      {/* Hero Slider */}
      <section className={styles.hero}>
        {heroSlides.map((slide, i) => (
          <div
            key={i}
            className={`${styles.heroSlide} ${
              i === currentSlide ? styles['heroSlide--active'] : ''
            }`}
            style={{ backgroundImage: `url(${slide.bg})` }}
          >
            <div className={styles.heroOverlay} />
            <div className={styles.heroContent}>
              <h1 className={styles.heroTitle}>{slide.title}</h1>
              <p className={styles.heroSubtitle}>{slide.subtitle}</p>
              <div className={styles.heroButtons}>
                <Button
                  variant="primary"
                  size="lg"
                  onClick={() => navigate('/shop')}
                >
                  {CONTENT.BTN_SHOP_NOW}
                </Button>
                <Button
                  variant="secondary"
                  size="lg"
                  onClick={() => navigate('/about')}
                >
                  {CONTENT.BTN_OUR_STORY}
                </Button>
              </div>
            </div>
          </div>
        ))}

        {/* Slide Dots */}
        <div className={styles.slideDots}>
          {heroSlides.map((_, i) => (
            <button
              key={i}
              className={`${styles.dot} ${
                i === currentSlide ? styles['dot--active'] : ''
              }`}
              onClick={() => setCurrentSlide(i)}
              aria-label={`Go to slide ${i + 1}`}
            />
          ))}
        </div>
      </section>

      {/* Trust Badges */}
      <section className={styles.trustBadges}>
        <div className={styles.trustGrid}>
          {TRUST_BADGES.map((badge, i) => (
            <div key={i} className={styles.trustItem}>
              <span className={styles.trustIcon}>{badge.icon}</span>
              <span className={styles.trustText}>{badge.text}</span>
            </div>
          ))}
        </div>
      </section>

      {/* Categories */}
      <section className={styles.categories}>
        <div className={styles.container}>
          <h2 className={styles.sectionTitle}>{CONTENT.SECTION_EVERYDAY_JEWELLERY}</h2>
          <p className={styles.sectionSubtitle}>{CONTENT.EVERYDAY_SUBTITLE}</p>
          <div className={styles.categoryGrid}>
            {CATEGORIES.map((cat) => (
              <div
                key={cat.name}
                className={styles.categoryCard}
                onClick={() => navigate(`/shop?category=${cat.name}`)}
              >
                <div className={styles.categoryImageWrapper}>
                  <img src={cat.img} alt={cat.name} />
                </div>
                <p className={styles.categoryName}>{cat.name}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Featured Collection Banner */}
      <section className={styles.featuredBanner}>
        <div className={styles.featuredContent}>
          <div>
            <p className={styles.featuredLabel}>{featuredCollection.label}</p>
            <h2 className={styles.featuredTitle}>{featuredCollection.title}</h2>
            <p className={styles.featuredText}>{featuredCollection.description}</p>
            <Button variant="primary" size="lg" onClick={() => navigate('/shop')}>
              Shop Collection
            </Button>
          </div>
          <div className={styles.featuredImage}>
            <img src={featuredCollection.image} alt="Fine Gold Collection" />
          </div>
        </div>
      </section>

      {/* Shop By Occasion */}
      <section className={styles.occasionSection}>
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Shop By Occasion</h2>
            <p className={styles.sectionSubtitle}>Find the perfect jewellery for every celebration and everyday moment.</p>
          </div>
          <div className={styles.occasionGrid}>
            {occasions.map((occasion) => (
              <button
                key={occasion.name}
                className={styles.occasionCard}
                onClick={() => navigate('/shop')}
              >
                <div className={styles.occasionImageWrapper}>
                  <img src={occasion.image} alt={occasion.name} />
                </div>
                <span>{occasion.name}</span>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Trending Collections removed to keep homepage product-focused */}

      {/* Why Lumoria Section */}
      <section className={styles.benefitsSection}>
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Why Lumoria</h2>
            <p className={styles.sectionSubtitle}>Experience the premium difference in every detail.</p>
          </div>
          <div className={styles.benefitsGrid}>
            {lumoriaBenefits.map((benefit) => (
              <div key={benefit.title} className={styles.benefitCard}>
                <div className={styles.benefitIcon}>{benefit.icon}</div>
                <h3>{benefit.title}</h3>
                <p>{benefit.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Best Sellers */}
      <section className={styles.favoritesSection}>
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Best Sellers</h2>
            <p className={styles.sectionSubtitle}>Top-rated jewellery loved by our customers.</p>
          </div>
          <div className={styles.productsGrid}>
            {(bestSellers.length ? bestSellers : favoriteProducts.slice(0,4)).map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        </div>
      </section>

      {/* New Arrivals */}
      <section className={styles.favoritesSection}>
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>New Arrivals</h2>
            <p className={styles.sectionSubtitle}>Discover the latest additions to Lumoria.</p>
          </div>
          <div className={styles.productsGrid}>
            {(newArrivals.length ? newArrivals : PRODUCTS.slice(0,4)).map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        </div>
      </section>

      {/* Craftsmanship section removed to avoid non-product lifestyle content */}

      {/* Customer Testimonials */}
      <section className={styles.testimonialsSection}> 
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Customer Testimonials</h2>
            <p className={styles.sectionSubtitle}>Luxury reviews from women who love Lumoria every day.</p>
          </div>
          <div className={styles.testimonialGrid}>
            {homepageTestimonials.map((item) => (
              <div key={item.name} className={styles.testimonialCard}>
                <div className={styles.testimonialMeta}>
                  <span className={styles.testimonialName}>{item.name}</span>
                  <span className={styles.testimonialLocation}>{item.location}</span>
                </div>
                <div className={styles.testimonialRating}>{'⭐'.repeat(item.rating)}</div>
                <p className={styles.testimonialText}>{item.review}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Instagram Inspired Gallery */}
      <section className={styles.instagramSection}>
        <div className={styles.container}>
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>#StyledWithLumoria</h2>
            <p className={styles.sectionSubtitle}>A curated visual story of jewellery worn with effortless glamour.</p>
          </div>
          <div className={styles.instagramGrid}>
            {galleryImages.map((src, index) => (
              <div key={index} className={styles.instagramItem}>
                <img src={src} alt={`Lumoria styled look ${index + 1}`} />
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Removed store, newsletter and SEO blocks to keep homepage product-focused as requested */}

      {/* Top Styles */}
      <section className={styles.topStyles}>
        <div className={styles.container}>
          <h2 className={styles.sectionTitle}>{CONTENT.SECTION_TOP_STYLES}</h2>

          {/* Tabs */}
          <div className={styles.tabs}>
            {tabs.map((tab) => (
              <button
                key={tab}
                className={`${styles.tab} ${
                  activeTab === tab ? styles['tab--active'] : ''
                }`}
                onClick={() => setActiveTab(tab)}
              >
                {tab}
              </button>
            ))}
          </div>

          {/* Products Grid */}
          <div className={styles.productsGrid}>
            {filtered.map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>

          {/* View All Button */}
          <div className={styles.viewAllContainer}>
            <Button
              variant="secondary"
              size="lg"
              onClick={() => navigate('/shop')}
            >
              {CONTENT.BTN_VIEW_ALL}
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default HomePage;
